-- Arctic research-station reference supplied by the user, enriched with current verification.
-- User rows are kept as reference data; verified current status comes only from named external sources.
CREATE TABLE IF NOT EXISTS arctic_research_stations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  source_key TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  location TEXT,
  operating_country TEXT,
  established TEXT,
  summer_population TEXT,
  winter_population TEXT,
  latitude REAL,
  longitude REAL,
  coordinate_precision TEXT NOT NULL DEFAULT 'none',
  coordinate_source TEXT,
  source_kind TEXT NOT NULL,
  source_url TEXT NOT NULL,
  verification_status TEXT NOT NULL,
  verification_source TEXT,
  verification_url TEXT,
  geographic_scope TEXT NOT NULL DEFAULT 'unmapped',
  verification_note TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_arctic_research_status ON arctic_research_stations(verification_status);
CREATE INDEX IF NOT EXISTS idx_arctic_research_scope ON arctic_research_stations(geographic_scope);

